"use client";
import { useState } from 'react';
import { supabase } from '@/utils/supabase'; 
import { statesAndLgas } from '@/utils/nigeriaData'; 

export default function ReportPage() {
  const [selectedState, setSelectedState] = useState("");
  const [file, setFile] = useState<File | null>(null);
  const [loading, setLoading] = useState(false);

  const MAX_FILE_SIZE = 5 * 1024 * 1024; 

  const handleSubmit = async (e: any) => {
    e.preventDefault();
    setLoading(true);

    const formData = new FormData(e.target);
    const reportData = {
      state: formData.get("state"),
      lga: formData.get("lga"),
      category: formData.get("category"),
      description: formData.get("description"),
    };

    try {
      if (file && file.size > MAX_FILE_SIZE) {
        alert("File too large! Please keep it under 5MB.");
        setLoading(false);
        return;
      }

      let mediaUrl = "";
      if (file) {
        const fileExt = file.name.split('.').pop();
        const fileName = `${Math.random()}.${fileExt}`;
        const { data, error } = await supabase.storage
          .from('reports-media')
          .upload(fileName, file);

        if (error) throw error;
        mediaUrl = data.path;
      }

      const { error: dbError } = await supabase
        .from('reports')
        .insert([{ ...reportData, media_url: mediaUrl }]);

      if (dbError) throw dbError;

      alert("Report submitted successfully!");
      e.target.reset();
      setFile(null);
    } catch (err) {
      console.error(err);
      alert("Submission failed. Make sure your Supabase table is set up.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-2xl mx-auto p-8 bg-white shadow-2xl mt-10 rounded-2xl border-2 border-black">
      <h1 className="text-3xl font-extrabold mb-2 text-green-800">Submit a Report</h1>
      <p className="text-black font-bold mb-8">Fill in the details below to report a civic issue in your area.</p>
      
      <form onSubmit={handleSubmit} className="space-y-6">
        {/* State Selection */}
        <div>
          <label className="block font-black text-black mb-2 uppercase text-sm tracking-wide">State</label>
          <select 
            name="state" 
            required 
            className="w-full p-3 border-2 border-black rounded-lg text-black bg-white focus:ring-2 focus:ring-green-600 outline-none font-bold"
            onChange={(e) => setSelectedState(e.target.value)}
          >
            <option value="" className="text-black">Select State</option>
            {Object.keys(statesAndLgas).sort().map(state => (
              <option key={state} value={state} className="text-black">{state}</option>
            ))}
          </select>
        </div>

        {/* Dynamic LGA Selection */}
        <div>
          <label className="block font-black text-black mb-2 uppercase text-sm tracking-wide">LGA</label>
          <select 
            name="lga" 
            required 
            className="w-full p-3 border-2 border-black rounded-lg text-black bg-white focus:ring-2 focus:ring-green-600 outline-none disabled:bg-gray-200 font-bold" 
            disabled={!selectedState}
          >
            <option value="" className="text-black">Select LGA</option>
            {selectedState && statesAndLgas[selectedState].sort().map(lga => (
              <option key={lga} value={lga} className="text-black">{lga}</option>
            ))}
          </select>
        </div>

        {/* Category */}
        <div>
          <label className="block font-black text-black mb-2 uppercase text-sm tracking-wide">Category</label>
          <select name="category" required className="w-full p-3 border-2 border-black rounded-lg text-black bg-white focus:ring-2 focus:ring-green-600 outline-none font-bold">
            <option value="Roads" className="text-black">Roads/Infrastructure</option>
            <option value="Security" className="text-black">Security</option>
            <option value="Health" className="text-black">Healthcare</option>
            <option value="Education" className="text-black">Education</option>
            <option value="Other" className="text-black">Other</option>
          </select>
        </div>

        {/* Evidence Upload */}
        <div>
          <label className="block font-black text-black mb-2 uppercase text-sm tracking-wide">Evidence (Photo/Video - Max 5MB)</label>
          <input 
            type="file" 
            accept="image/*,video/*" 
            onChange={(e) => setFile(e.target.files?.[0] || null)}
            className="w-full text-sm text-black font-bold file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-2 file:border-black file:text-sm file:font-black file:bg-white file:text-black hover:file:bg-black hover:file:text-white cursor-pointer"
          />
        </div>

        {/* Description */}
        <div>
          <label className="block font-black text-black mb-2 uppercase text-sm tracking-wide">Description</label>
          <textarea 
            name="description" 
            required 
            placeholder="Provide specific details about the issue..."
            className="w-full p-3 border-2 border-black rounded-lg text-black bg-white h-32 focus:ring-2 focus:ring-green-600 outline-none font-bold placeholder:text-gray-600"
          ></textarea>
        </div>

        <button 
          type="submit" 
          disabled={loading}
          className="w-full bg-green-700 text-white py-4 rounded-xl font-black text-xl shadow-[4px_4px_0px_0px_rgba(0,0,0,1)] hover:shadow-none hover:translate-x-1 hover:translate-y-1 active:bg-green-800 disabled:bg-gray-400 transition-all border-2 border-black"
        >
          {loading ? "PROCESSING..." : "SUBMIT REPORT"}
        </button>
      </form>
    </div>
  );
}